import pathlib,json,copy,yaml,datetime
class Strict(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 loader.flatten_mapping(node);d={}
 for k,v in node.value:
  key=loader.construct_object(k,deep=deep)
  if key in d:raise ValueError('duplicate key')
  d[key]=loader.construct_object(v,deep=deep)
 return d
Strict.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load(name):return yaml.load(pathlib.Path(name).read_text(encoding='utf-8'),Loader=Strict)

BASE={'auth_enabled': True, 'server': {'http_listen_port': 3100}, 'common': {'path_prefix': '/var/lib/loki', 'replication_factor': 1, 'ring': {'kvstore': {'store': 'inmemory'}}, 'storage': {'filesystem': {'chunks_directory': '/var/lib/loki/chunks', 'rules_directory': '/var/lib/loki/rules'}}}, 'schema_config': {'configs': [{'from': '2024-01-01', 'store': 'tsdb', 'object_store': 'filesystem', 'schema': 'v13', 'index': {'prefix': 'index_', 'period': '24h'}}]}, 'limits_config': {'allow_structured_metadata': True, 'ingestion_rate_strategy': 'global', 'ingestion_rate_mb': 0, 'ingestion_burst_size_mb': 0, 'per_stream_rate_limit': '20MB', 'per_stream_rate_limit_burst': '40MB'}}
d=load("loki.yaml");b=copy.deepcopy(BASE)
l=d['limits_config'];expected={'ingestion_rate_mb':4,'ingestion_burst_size_mb':6,'per_stream_rate_limit':'1MB','per_stream_rate_limit_burst':'2MB'}
for k,v in expected.items():
 assert type(l[k])==type(v) and l[k]==v
 b['limits_config'][k]=v
assert d==b

